{
  "bioavailability_prediction": "low",
  "confidence": "high",
  "revision_action": "strengthen",
  "supportive_card_ids": ["C53","C04","C61","C149","C139","C141","C130","C126","C129","C144","C151","C138"],
  "contradictory_card_ids": ["C117","C155","C164"],
  "prediction_basis_card_ids": ["C53","C04","C61","C149","C139","C141","C130","C129","C144","C151","C138"],
  "claims": [
    {
      "claim": "The closest L4 analog, EXP3174 (M01), shares the dianionic imidazole-acid/N-benzyl-aryl acid scaffold with the query and showed very low Caco-2 A→B permeability (2.50 × 10⁻⁸ cm/s) with high B→A permeability (25.6 × 10⁻⁸ cm/s); A→B remained very low with P-gp or BCRP inhibition (C130, C141). This is affirmative measured permeability/efflux evidence that the query's dianionic dicarboxylate scaffold is poorly absorbed.",
      "card_ids": ["C149","C139","C130","C141"]
    },
    {
      "claim": "Losartan (M02), a less charged sartan analog with one tetrazole acid and an alcohol, showed modest A→B permeability (reported ~0.5–1.6 × 10⁻⁶ cm/s; C138, C129, C126) with B→A efflux (C144, C151); the query has two carboxylates and logD 0.56, so it is expected to be less permeable.",
      "card_ids": ["C138","C129","C126","C144","C151"]
    },
    {
      "claim": "Prior direct low-F analogs remain relevant: azosemide human F ≈10–20.4% (C53, C04) and bumetanide rat intraduodenal F ≈15.8% (C61) support F < 20% for highly ionized carboxylates.",
      "card_ids": ["C53","C04","C61"]
    },
    {
      "claim": "Positive absorption records for other L4 molecules (HR720 significantly absorbed in rats, C117; irbesartan fraction absorbed 60–80%, C155; olmesartan Caco-2 A→B 2.69 × 10⁻⁶ cm/s, C164) involve different acid/charge topologies or lack F data and do not provide threshold-relevant evidence for the query.",
      "card_ids": ["C117","C155","C164"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "intestinal_absorption_permeability",
      "applicability": "moderate",
      "direction": "supportive",
      "decision_effect": "strengthened",
      "card_ids": ["C149","C139","C141","C130","C126","C129","C144","C151","C138"]
    }
  ],
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for the query molecule.",
    "No query-specific Caco-2/MDCK permeability, efflux, or solubility data.",
    "No matched oral-versus-IV exposure, dose, formulation, or prandial condition for the query.",
    "EXP3174 is a metabolite and not identical to the query; transfer depends on structural analogy.",
    "Possible active uptake transporters or formulation effects for the query are not assessed.",
    "Positive absorption records for HR720, irbesartan, and olmesartan are for different acid/charge topologies and lack F thresholds."
  ],
  "decision_summary": "Strengthened low: L4 adds close-analog EXP3174 with very low Caco-2 A→B permeability and high efflux, consistent with the query's dianionic dicarboxylate state and low logD. Positive absorption records for less transferable analogs do not outweigh this. F < 20% remains better supported."
}

